// ora-mod-om — generated by tools/merge.js: src/ora-mod-om-*.js plus matching questions from the Oracle role banks (tools/modules.js).
// Oracle Modules — Order Management & Pricing. Format: [topic, question, answer, 'B'|'D']
QB['ora-mod-om'] = (QB['ora-mod-om'] || []).concat([
['Setup', 'What are the main Order Management setups?',
`- **Order types/transaction types** and **document numbering**.
- **Orchestration processes** and **process assignment rules**.
- **Fulfillment** connectors (shipping, receiving, manufacturing, external).
- **Hold codes**, **processing constraints**, **business rules** (e.g. line defaults).
- **Pricing** setups (price lists, discount lists, strategies, segments).
- **Customer** and **item** prerequisites; **GOP** sourcing.`, 'B'],

['Orchestration', 'What is jeopardy in order orchestration?',
`- Each orchestration step has planned durations; **jeopardy** compares expected vs planned completion and flags lines as **low/medium/high** risk of missing the promised date.
- Order managers act on high-jeopardy lines (expedite, reschedule).`, 'D'],

['Orchestration', 'What are fulfillment lines?',
`- The unit orchestration works on — a sales order line can split into multiple **fulfillment lines** (e.g. partial shipments, different warehouses, configured components).
- Each has its own status, schedule and orchestration process instance.`, 'D'],

['Pricing', 'What are pricing segments and strategy assignments?',
`- **Pricing segment**: groups customers/orders for pricing (e.g. "Gold distributors").
- **Strategy assignment** rules assign a **pricing strategy** (price lists + discounts) to a segment or context (customer, BU, channel).
- Pricing algorithm uses the strategy to compute prices on orders.`, 'D'],

['Returns', 'How do you set up returns in Fusion OM?',
`- **Return orders** (RMA) referencing original orders.
- **Return reasons** and policies (e.g. credit only, replacement).
- Orchestration for returns: receive → inspect → credit.
- AR credit memo via billing; inventory receipt into return subinventory.`, 'B'],

['Integration', 'How do orders flow from a third-party e-commerce site into Fusion?',
`- **Sales order REST API** or **order import (FBDI/web services)** via OIC.
- Map customers, items, prices (frozen or re-priced), ship methods.
- Status updates back to e-commerce via business events/REST.
- Error handling and monitoring for failed imports.`, 'D'],

['Interview', 'What would you emphasize as an OM/O2C contractor?',
`- Orchestration design and change management.
- GOP and sourcing.
- Pricing setup experience.
- Integration with Shipping, AR and Revenue.
- Troubleshooting stuck orders (with a real story).`, 'B']
]);

QB['ora-mod-om'] = (QB['ora-mod-om'] || []).concat([["Order Management","How would you architect Order Management for very high order volumes (e.g. 200k lines/day)?","- **Order import** via bulk/REST in parallel streams, with throttling and retry.\n- **Orchestration** processes kept lean (minimal steps; avoid unnecessary waits).\n- **Scheduling**: GOP tuned (collections frequency, ATP rules); batch scheduling for non-urgent lines.\n- **Pick release** in waves by warehouse with performance-tested release rules.\n- **AutoInvoice** volumes split by batch source and run frequently.\n- **Performance testing** with production-like volumes; Oracle engagement for capacity.\n- **Monitoring** and alerting on backlog.","D"],["Order Management","How would you design order orchestration to support omnichannel fulfillment (ship from store, BOPIS)?","- **Fulfillment nodes**: DCs, stores, suppliers (drop ship) — modeled as orgs or external fulfillment systems.\n- **Sourcing logic** by distance, inventory, cost and capacity (GOP rules or an external order-routing engine).\n- **Orchestration processes** per fulfillment type: ship from DC, ship from store, buy online pick up in store, drop ship.\n- **Inventory visibility** across nodes (store inventory feeds).\n- **Change and cancel** handling across systems.\n- **Returns anywhere** with routing to the right node.","D"],["Order Management","How do you integrate CPQ with Oracle Order Management?","- CPQ (Oracle CPQ or third-party) owns **configuration, pricing and quoting**.\n- Accepted quote → **order** in OM (via native integration or OIC/REST), carrying configuration, prices and discounts.\n- Decide whether **pricing** in OM recalculates or **freezes** CPQ prices.\n- **Configured items** created in OM/Configurator for ATO.\n- **Status updates** back to CPQ/CRM.\n- Customer and item master alignment across systems.","D"],["Order Management","How would you design order capture from multiple channels with agent support?","- **APIs** for e-commerce/CPQ/EDI orders into OM.\n- **Agent** for email/PDF purchase orders: extracts lines, matches customer items, creates **draft orders** for review.\n- **Validation** rules and pricing in OM.\n- **Human review** queue for low-confidence extractions.\n- Monitor extraction accuracy and order cycle time.","D"],["Order Management","Explain the Order-to-Cash flow from the SCM side.","- **Sales order** created (manually, via import, or from a CPQ/CRM system).\n- **Orchestration** process starts — order is validated, priced, and **scheduled** (Global Order Promising checks availability).\n- **Reserve** inventory, then **pick release** creates pick tasks/move orders.\n- **Pick confirm** and **pack**.\n- **Ship confirm** — inventory is issued, the order line is fulfilled.\n- **Billing** — lines are sent to Receivables (AutoInvoice) for invoicing.\n- **Revenue and COGS** recognized; receipts applied in AR.","B"],["Order Management","What is order orchestration in Fusion Order Management?","Orchestration is the process engine that drives each order line through fulfillment.\n- **Orchestration processes** define steps (schedule, reserve, ship, invoice) and their order.\n- **Fulfillment lines** are assigned to a process via process assignment rules (e.g. by order type or item).\n- Steps call **fulfillment systems** (Shipping, Receiving, Manufacturing, a 3PL) through connectors.\n- Supports **jeopardy** (lateness warnings), **change management** (what to do if the order changes mid-process) and **holds**.\n\nEBS equivalent: Order Management workflows.","D"],["Order Management","What are holds in Order Management and how are they applied?","Holds stop an order or line from progressing.\n- **Credit check hold** — customer exceeds credit limit.\n- **Manual holds** — e.g. pricing review, export compliance.\n- **Hold definitions** specify where the hold stops the process (e.g. before shipping or before invoicing).\n- Applied manually or automatically by rules; released by authorized users with a reason.\n\nTip: Mention you checked who can release holds — it's a control point.","B"],["Order Management","How does pricing work for sales orders in Fusion?","Fusion uses **Pricing Administration**:\n- **Price lists** — base price per item and UOM.\n- **Discount lists** — percentage or amount discounts.\n- **Pricing strategies** combine price lists and discounts and are assigned to customers or segments via **pricing segments** and **strategy assignment rules**.\n- **Pricing algorithms** calculate the final price; **charges** (e.g. freight) can be added.\n- **Shipping charges** and **cost-plus** pricing are possible.\n\nEBS uses Advanced Pricing modifiers and qualifiers.","D"],["Order Management","What is drop shipment?","The supplier ships directly to your customer — the goods never enter your warehouse.\n- A sales order line with **drop ship** source type creates a **requisition/PO** to the supplier.\n- The supplier ships to the customer; you record a **logical receipt** (and logical shipment) when they confirm.\n- AP pays the supplier invoice; AR invoices the customer.\n- Inventory is not physically touched, but accounting still flows through receipt and cost.","D"],["Order Management","What is back-to-back ordering?","A sales order line triggers a **dedicated purchase (or work order)** for that customer, and the supply is **reserved** to the order when it arrives.\n- Received into your warehouse (unlike drop ship), then shipped to the customer.\n- Used for items you don't stock but want to control/inspect.\n- The reservation ensures the incoming supply isn't used for other orders.","D"],["Order Management","How do returns (RMA) work in Order Management?","- Create a **return order** (RMA) referencing the original sales order where possible — keeps price and lot/serial info.\n- Customer ships back; **receive** the return in Receiving (with inspection if needed).\n- Inventory increases (or goes to a reject/MRB subinventory).\n- A **credit memo** is created in AR through invoicing of the return line.\n- Return reasons are tracked for analysis.","B"],["Order Management","What are the main sales order statuses you see in Fusion?","- **Draft** → **Processing** (submitted; orchestration running) → **Awaiting Shipping/Billing** at line level → **Shipped** → **Billed** → **Closed**.\n- Lines can also be **On Hold**, **Backordered** or **Canceled**.\n- Fulfillment line status tells you exactly which step a line is at.","B"],["Order Management","How would you design the O2C process for a company selling through e-commerce and EDI?","- **Order capture**: e-commerce via REST order import (or OIC); EDI 850 via B2B provider → OM.\n- **Validation and pricing**: pricing in Fusion or honor channel price.\n- **Orchestration**: standard ship, drop ship, back-to-back.\n- **GOP** for promising; ATP shown to customers.\n- **Shipping** with carrier integration; **ASN (856)** back to EDI customers; tracking to e-commerce.\n- **Invoicing** (810 for EDI), payments for e-commerce (card settlement).\n- **Returns** process in both channels.\n- **Monitoring** of order import failures.","D"],["Order Management","How do you handle order holds for export compliance?","- Integrate with a **trade compliance** solution (Oracle Global Trade Management or third party) to screen parties (denied party screening) and items (classification, licenses).\n- Orchestration step triggers screening; failures place an **export compliance hold**.\n- Compliance team reviews and releases or cancels.\n- Audit trail for regulators.\n\nCommon for tech and pharma companies selling internationally.","D"],["Order Management","How do you design GOP and sourcing for multi-warehouse fulfillment?","- **Sourcing rules** by region (customer ship-to zone → nearest DC, with alternates ranked).\n- **ATP rules** (supply types considered, infinite time fence, lead times).\n- **Allocation** for constrained items by channel/customer priority.\n- **Split shipments** policy (allowed or not).\n- Run **collections** frequently for accurate supply.\n- Measure promise accuracy and adjust rules.","D"],["Order Management","How do you design order holds and approvals for high-value or unusual orders?","- **Credit check** at booking/scheduling via Credit Management.\n- **Pricing approvals** for discounts beyond thresholds (via approval rules or CPQ upstream).\n- **Manual review holds** triggered by rules (order value > $X, new customer, high-risk country).\n- Holds defined by **step** (pre-schedule vs pre-ship).\n- Clear owners for release and SLAs.\n- Dashboard of orders on hold by reason and age.","D"],["Order Management","How would you design order hold management with AI assistance?","- **Holds** applied by rules (credit, pricing, compliance).\n- **Agent** summarizes each held order: reason, customer history, recommended action.\n- Credit analysts/order admins decide and release (human in the loop).\n- Track hold duration and reasons; fix recurring root causes.","D"],["Supply Chain Orchestration","What is Supply Chain Financial Orchestration (SFO) and when do you need it?","SFO handles the **financial side of supply chain flows that cross legal entities or business units** — e.g. a US company buys goods that are received by its Mexican warehouse, or a sales BU sells goods shipped from another entity's warehouse.\n\n- **Financial orchestration flows** (procurement or shipment flows) define the chain of entities, **transfer pricing rules** and **documentation** (intercompany AR/AP invoices).\n- Physical movement happens once; SFO creates the **logical** intercompany transactions and accounting in each entity.\n- Common for global companies with central procurement or sales entities.\n\nTip: Mention an example flow you configured and how you tested the intercompany invoices.","D"],["Order Management","How do you design orchestration processes for different order types?","- Group fulfillment patterns: **standard ship**, **drop ship**, **back-to-back**, **configured items (ATO)**, **services/subscriptions**, **returns**.\n- Create an orchestration process per pattern (or copy seeded ones) with steps, task types and **change management** rules.\n- **Process assignment rules** route lines by order type, item type, BU or source.\n- Set **planning/lead times** per step for jeopardy calculation.\n- Test change scenarios: quantity change after scheduling, cancel after pick, change ship-to after release.","D"],["Order Management","What is Global Order Promising (GOP) and how do sourcing rules affect it?","GOP checks **availability** and promises a date for order lines.\n- Considers on-hand, supply (POs, work orders, transfers), lead times and allocations.\n- **Sourcing rules and assignment sets** tell GOP which warehouses (and suppliers) can fulfill — with ranks and percentages.\n- Supports **ATP** (available to promise) and **CTP** (capable to promise — checks component and resource availability for make items).\n- Data is collected from the transaction system into the planning data repository — **data collections** must run regularly.\n\nTip: A common issue: GOP can't schedule because collections didn't run or sourcing isn't assigned.","D"],["Order Management","How do you handle changes to a sales order that is already in fulfillment?","- Fusion OM uses **change management** in the orchestration process: each step defines whether a change is allowed and what **compensation** pattern runs (e.g. cancel the reservation and reschedule, update the shipment line, or reject the change).\n- Changes from source systems come as **revisions**; OM compares and applies them.\n- After **ship confirm**, changes are blocked; you use returns or credit memos instead.\n- Constraints (processing constraints) can block specific changes by role or status.","D"],["Order Management","What are processing constraints?","Rules that **prevent changes or actions** on orders based on conditions — e.g. \"cannot change the ship-to address once the line is pick-released\", or \"only order administrators can change price after booking\".\n- Defined on entities (order header, line) and attributes, with conditions (status) and roles.\n- Prevent data corruption mid-fulfillment and enforce controls.\n- Seeded constraints exist; you add custom ones for business rules.","D"],["Pricing","How would you set up customer-specific pricing with volume discounts?","- Create a **price list** with base prices.\n- Create a **discount list** with **tiered** (volume) adjustments — e.g. 1–99 units 0%, 100–499 5%, 500+ 10%.\n- Build a **pricing strategy** combining the price list and discount list.\n- Create a **pricing segment** for the customer (or customer class) and **assign the strategy** to that segment.\n- Test with orders at each tier and check the price breakdown on the order line.","D"],["Order Management","How do configured (ATO) items flow through Order Management?","- **Assemble-to-order (ATO)** model items are configured by the customer (via **Configurator**) at order entry.\n- The selected options create a **configured item** (unique item/BOM) when the order is scheduled.\n- A **work order** (or supply from a supplier for buy ATO) is created and reserved to the order.\n- After completion, it ships like a normal item.\n- Pricing comes from model + options.\n\nPTO (pick-to-order) kits are picked from stock rather than built.","D"],["Order Management","How do you troubleshoot a sales order line that won't schedule?","- Check **GOP**: is there supply? Are sourcing rules/assignment sets correct for the ship-to and item?\n- **Data collections** recently run?\n- Item enabled in the warehouse and for shipping? Customer/ship-to valid?\n- Holds on the order?\n- Orchestration process assignment and step errors.","D"]]);
